function tileFace(id,interactive=false,onClick=null,disabled=false,mini=false){
 const type=tileType(id),kind=suit(id),num=type<27?type%9+1:0;
 const tile=mk(interactive?'button':'span','wcg-tile wcg-tile-face '+kind+(mini?' mini':''));
 if(interactive){tile.type='button';tile.disabled=disabled;if(onClick)tile.onclick=onClick;}
 const art=mk('span','wcg-tile-art '+kind);
 if(kind==='wan'){
  art.append(mk('span','wcg-tile-number',num),mk('span','wcg-tile-wan','萬'));
 }else if(kind==='honor'){
  const glyph=['東','南','西','北','中','發','白'][type-27]||'';
  art.append(mk('span','wcg-tile-honor'+(type===31?' red':type===32?' green':''),glyph));
 }else{
  for(let i=0;i<num;i++)art.append(mk('i',kind==='tong'?'wcg-tile-dot shade-'+i%3:'wcg-tile-bamboo shade-'+i%3));
 }
 tile.append(art);
 const tileAsset=type<9?'Man'+(type+1):type<18?'Pin'+(type-8):type<27?'Sou'+(type-17):['Ton','Nan','Shaa','Pei','Chun','Hatsu','Haku'][type-27];
 attachGameAsset(tile,'mahjong/'+tileAsset+'.svg');
 tile.setAttribute('aria-label',tileName(id));
 return tile;
}
function seatPosition(index,anchor,length){
 const relative=(index-anchor+length)%length;
 return (length===3?['bottom','left','top']:['bottom','left','top','right'])[relative];
}
// Tabler Icons (MIT): crown-filled, embedded from the upstream SVG.
const LANDLORD_CROWN_ICON = '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M19 19h-14c-.5 0 -.9 -.3 -1 -.8l-2 -10c0 -.4 .1 -.8 .5 -1.1c.4 -.2 .8 -.2 1.1 0l4.1 3.3l3.4 -5.1c.4 -.6 1.3 -.6 1.7 0l3.4 5.1l4.1 -3.3c.3 -.3 .8 -.3 1.1 0c.4 .2 .5 .6 .5 1.1l-2 10c0 .5 -.5 .8 -1 .8z"/></svg>';
function tableSeat(g,index,anchor,renderPlayer){
 const player=g.players[index],current=g.status==='playing'&&g.turn===index;
 const position=seatPosition(index,anchor,g.players.length);
 const holder=mk('div','wcg-table-seat wcg-table-seat-'+position+(current?' active':''));
 holder.dataset.memberId=player.id;
 const role=g.gameType==='cards'?(index===g.landlord?'地主':'农民'):index===0?'庄家':'玩家';
 const profile=typeof renderPlayer==='function'?
  renderPlayer(player,index,current,{gameType:g.gameType,role,position}):mk('div','wcg-player'+(current?' active':''),player.name);
 const seatCount=g.gameType==='cards'
  ?(position==='top'||position==='bottom'?role+' · '+g.hands[index].length+' 张':'剩余 '+g.hands[index].length+' 张')
  :g.discards[index].length+' 弃牌';
 const roleTag=mk('span','wcg-seat-role'+(role==='地主'?' landlord':''),role);
 const countTag=mk('span','wcg-seat-count'+(g.gameType==='cards'&&role==='地主'?' landlord':''),seatCount);
 if(g.gameType==='cards'&&index===g.landlord){
  roleTag.insertAdjacentHTML('afterbegin',LANDLORD_CROWN_ICON);
  if(position==='bottom')countTag.insertAdjacentHTML('afterbegin',LANDLORD_CROWN_ICON);
 }
 holder.append(roleTag,profile,countTag);
 if(player.id!=='user'){
  const backs=mk('div',g.gameType==='mahjong'?'wcg-card-backs wcg-mahjong-backs':'wcg-card-backs');
  const count=Math.min(g.gameType==='cards'?5:6,g.hands[index].length);
  for(let i=0;i<count;i++)backs.append(mk('i',g.gameType==='mahjong'?'wcg-tile-back':'wcg-card-back'));
  holder.append(backs);
 }
 return holder;
}
function renderTable(g,{canPlay=false,onMove=()=>{},renderPlayer=null}={}){
 const scene=mk('section','wcg-scene wcg-scene-'+g.gameType);
 scene.dataset.status=g.status;
 // Keep the same hand mounted while its durable move is being committed.
 let submitting=false;
 const submit=async move=>{
  if(submitting)return;
  submitting=true;
  const inputs=[...scene.querySelectorAll('button')],states=inputs.map(node=>node.disabled);
  inputs.forEach(node=>{node.disabled=true;});scene.setAttribute('aria-busy','true');
  try{await onMove(move);}finally{
   submitting=false;scene.setAttribute('aria-busy','false');
   inputs.forEach((node,i)=>{node.disabled=states[i];});
  }
 };
 const top=mk('div','wcg-scene-info');
 if(g.gameType==='mahjong'){
  top.append(mk('span','wcg-game-tag','好友麻将'),
   mk('span','wcg-game-round','第 '+(g.moves.length+1)+' 手'),
   mk('span','wcg-game-progress','余 '+g.wall.length+' 张'));
 }else{
  top.append(mk('span','wcg-game-round','第 '+(g.moves.length+1)+' 手'),
   mk('span','wcg-game-progress','三人斗地主 · 不计积分'));
 }
 scene.append(top);
 const table=mk('div','wcg-felt-table'),anchor=Math.max(0,g.players.findIndex(p=>p.id==='user'));
 if(g.gameType==='cards'){
  // The two opponents share the top half of the landscape playfield.
  const opponents=mk('div','wcg-opponents');
  g.players.forEach((_,i)=>{
   if(i===anchor)return;
   const seat=tableSeat(g,i,anchor,renderPlayer);
   seat.className+=' wcg-opponent';
   opponents.append(seat);
  });
  scene.append(opponents);
 }else if(g.gameType==='mahjong'){
  // North seating stays outside the playfield to avoid status overlap.
  const opponents=mk('div','wcg-mahjong-opponents');
  g.players.forEach((_,i)=>{
   if(i===anchor)return;
   const seat=tableSeat(g,i,anchor,renderPlayer);
   if(seat.classList.contains('wcg-table-seat-top'))opponents.append(seat);
   else table.append(seat);
  });
  scene.append(opponents);
 }else g.players.forEach((_,i)=>{
  if(i!==anchor)table.append(tableSeat(g,i,anchor,renderPlayer));
 });
 if(g.gameType==='cards'){
  const emblem=mk('div','wcg-card-felt-emblem');
  emblem.setAttribute('aria-hidden','true');
  emblem.append(mk('span','','♠'),mk('small','','NO. 01 / TONGHUA CLUB'));
  scene.append(emblem);
  scene.append(mk('small','wcg-card-table-version','翡翠俱乐部 · 三人对局'));
  const center=mk('div','wcg-played-area'),last=g.lastPlay;
  if(last){
   center.append(mk('small','wcg-center-caption',g.players[last.seat].name+' · 上一手'));
   const played=mk('div','wcg-played-cards');
   played.setAttribute('style','--wcg-played-count:'+last.cards.length);
   last.cards.forEach(id=>played.append(cardFace(id)));
   center.append(played);
  }else center.append(mk('small','wcg-center-caption','等待新一轮出牌'));
  table.append(center);
 }else{
  const walls=mk('div','wcg-mahjong-walls');
  ['top','left','right','bottom'].forEach((side,i)=>{
   const wall=mk('div','wcg-wall wcg-wall-'+side);
   const available=Math.ceil(Math.max(0,g.wall.length-i)/4);
   for(let k=0;k<Math.min(6,available);k++)wall.append(mk('i','wcg-wall-tile'));
   walls.append(wall);
  });
  table.append(walls);
  const rivers=mk('div','wcg-mahjong-rivers');
  g.discards.forEach((pile,i)=>{
   const side=seatPosition(i,anchor,4);
   const dense=(side==='left'||side==='right')&&pile.length>6?' wcg-river-dense':'';
   const river=mk('div','wcg-river-table wcg-river-table-'+side+dense);
   river.setAttribute('aria-label',g.players[i].name+'的弃牌');
   pile.slice(-18).forEach(id=>{
    const tile=tileFace(id,false,null,false,true),last=g.moves.at(-1);
    if(last?.seat===i&&last.tile===id)tile.className+=' wcg-last-discard';
    river.append(tile);
   });
   rivers.append(river);
  });
  const compass=mk('div','wcg-mahjong-compass');
  g.players.forEach((_,i)=>{
   const wind=mk('span','wcg-compass-wind wcg-compass-'+seatPosition(i,anchor,4)+
    (g.status==='playing'&&g.turn===i?' active':''),['東','南','西','北'][i]);
   compass.append(wind);
  });
  compass.append(mk('b','wcg-wall-count',g.wall.length),mk('small','wcg-wall-caption','剩余'));
   rivers.append(compass);
   table.append(rivers);
   if(g.gameType==='mahjong'&&Array.isArray(g.melds)){
    const laid=mk('div','wcg-mahjong-open-melds');
    g.melds.forEach((groups,seat)=>{
     if(!Array.isArray(groups)||!groups.length)return;
     const set=mk('div','wcg-mahjong-meld-seat wcg-mahjong-meld-'+seatPosition(seat,anchor,4));
     groups.forEach(m=>{
      const group=mk('div','wcg-mahjong-meld');
      (m.tiles||[]).forEach(id=>{
       if(m.kind==='concealed'&&g.players[seat]?.id!=='user'&&g.status==='playing')group.append(mk('i','wcg-tile-back'));
       else group.append(tileFace(id,false,null,false,true));
      });
      set.append(group);
     });
     laid.append(set);
    });
    table.append(laid);
   }
 }
 const turn=mk('div','wcg-table-turn',g.status==='finished'?(g.result||'对局结束'):
   g.pending?('等待 '+g.players[g.turn].name+' · '+(g.pending.kind==='robkong'?'抢杠响应':'吃碰杠胡响应')):
   '轮到 '+g.players[g.turn].name+(g.players[g.turn].id==='user'?' 出牌':' · 行动中'));
 turn.setAttribute('role','status');turn.setAttribute('aria-live','polite');
 if(g.gameType==='cards')table.querySelector('.wcg-played-area')?.append(turn);
 else if(g.gameType==='mahjong')scene.append(turn);
 else table.append(turn);
 const me=g.players.findIndex(p=>p.id==='user'),isTurn=me===g.turn&&g.status==='playing'&&canPlay;
 if(g.gameType==='mahjong')scene.dataset.mode=me>=0?'participate':'observer';
 if(me>=0){
  const area=mk('div','wcg-private-area');
  const hand=mk('div','wcg-hand '+(g.gameType==='cards'?'wcg-poker-hand':'wcg-mahjong-hand'));
  const controls=mk('div','wcg-game-controls');
  let mahjongClaimPanel=null;
  const tip=mk('small','wcg-hand-tip',g.status==='finished'?'对局已结束':isTurn?'请选择要出的牌':'等待其他玩家行动');
  if(g.gameType==='cards'){
   const selected=new Set(),buttons=new Map(),cards=[...g.hands[me]].sort((a,b)=>rank(b)-rank(a)||b-a);
   // Hand spacing follows the number of cards, not a fixed pixel width.
   hand.setAttribute('style','--wcg-hand-count:'+cards.length);


   const send=btn('出牌','wcg-primary wcg-game-send',()=>submit({cards:[...selected]}),true);
   const pass=btn('不出','wcg-secondary',()=>submit({pass:true}),!isTurn||!g.lastPlay||g.lastPlay.seat===me);
   const refresh=()=>{
    const valid=beats(combo([...selected]),g.lastPlay?.shape);
    send.disabled=!isTurn||!valid;
    for(const [id,node] of buttons){
     node.classList.toggle('chosen',selected.has(id));
     node.setAttribute('aria-pressed',String(selected.has(id)));
    }
    tip.textContent=g.status==='finished'?'对局已结束':!isTurn?'等待其他玩家行动':selected.size?(valid?'已选 '+selected.size+' 张':'当前牌型不能出'):'点选手牌后出牌';
   };
   cards.forEach(id=>{
    const card=cardFace(id,true,()=>{if(selected.has(id))selected.delete(id);else selected.add(id);refresh();},!isTurn);
    buttons.set(id,card);hand.append(card);
   });
   let hintOptions=null,hintIndex=0;
   const hint=btn('提示','wcg-secondary wcg-hint-button',()=>{
    hintOptions ||= candidates(g.hands[me]).filter(ids=>beats(combo(ids),g.lastPlay?.shape))
     .sort((a,b)=>Number(['bomb','rocket'].includes(combo(a).type))-Number(['bomb','rocket'].includes(combo(b).type)));
    const choice=hintOptions[hintIndex++%hintOptions.length];
    if(!choice){tip.textContent='没有能压过上家的牌';return;}
    selected.clear();choice.forEach(id=>selected.add(id));refresh();
   },!isTurn);
   cardActionIcon(pass,'pass','不出');
   cardActionIcon(hint,'hint','提示');
   cardActionIcon(send,'play','出牌');
   controls.append(pass,hint,send);refresh();
   }else{
    let selectedTile=null;
    const mahjong=window.WcMahjongRules;
    const legal=isTurn&&mahjong?mahjong.legalMoves(g,me):[];
    const canDiscard=isTurn&&!g.pending;
    const send=btn('出牌','wcg-primary wcg-game-send',()=>{if(selectedTile!==null&&canDiscard)return submit({tile:selectedTile});},true);
    const tiles=[...g.hands[me]].sort((a,b)=>tileType(a)-tileType(b)||a-b);
    hand.setAttribute('style','--wcg-hand-count:'+tiles.length);
    tiles.forEach(id=>{
     const tile=tileFace(id,true,()=>{
      if(selectedTile===id)selectedTile=null;else selectedTile=id;
      for(const child of hand.children){
       child.classList.toggle('chosen',Number(child.dataset.tileId)===selectedTile);
       child.setAttribute('aria-pressed',String(Number(child.dataset.tileId)===selectedTile));
      }
      send.disabled=!canDiscard||selectedTile===null;
      tip.textContent=selectedTile===null?'请选择要打出的牌':'已选择 '+tileName(selectedTile);
     },!canDiscard);
     tile.dataset.tileId=String(id);hand.append(tile);
    });
    mahjongClaimPanel=mk('div','wcg-mahjong-claim-panel');
    const claimMeta=mk('div','wcg-mahjong-claim-meta');
    const pending=g.pending;
    claimMeta.append(mk('strong','','接牌操作'),mk('span','',pending
     ?('来自 '+g.players[pending.from].name+' · '+tileName(pending.tile))
     :isTurn?'轮到你 · 选择牌后出牌':'等待其他玩家'));
    const claimActions=mk('div','wcg-mahjong-claim-actions');
    const picker=mk('div','wcg-mahjong-move-picker');picker.hidden=true;
    const useOptions=(options,label)=>{
     if(options.length===1){return submit(options[0]);}
     picker.replaceChildren(mk('strong','',label+' · 选择组合'));
     options.forEach(option=>{
      const choice=btn('', 'wcg-mahjong-move-choice',()=>{picker.hidden=true;return submit(option);});
      const ids=option.chi||[option.kong];
      ids.forEach(id=>choice.append(tileFace(id,false,null,false,true)));
      picker.append(choice);
     });
     const cancel=btn('取消','wcg-mahjong-move-cancel',()=>{picker.hidden=true;});
     picker.append(cancel);picker.hidden=false;
    };
    const actions=[
     ['过','PASS','pass',m=>m.pass],
     ['吃','CHI','chi',m=>m.chi],
     ['碰','PENG','peng',m=>m.peng],
     ['杠','GANG','gang',m=>m.kong!==undefined],
     ['胡','HU','win',m=>m.hu]
    ];
    actions.forEach(([label,english,type,matches])=>{
     const options=legal.filter(matches),enabled=options.length>0;
     const button=btn(label,'wcg-mahjong-claim-'+type,enabled?()=>useOptions(options,label):null,!enabled);
     button.append(mk('small','wcg-mahjong-claim-roman',english));
     button.title=enabled?label+' · 可操作':'当前不能'+label;
     claimActions.append(button);
    });
    mahjongClaimPanel.append(claimMeta,claimActions,picker);
    controls.append(send);
   }
  if(g.gameType==='cards'){
   const self=tableSeat(g,me,anchor,renderPlayer);
   self.className+=' wcg-self-seat';
   area.append(self,hand,tip);
  }else{
   const self=tableSeat(g,me,anchor,renderPlayer);self.className+=' wcg-self-seat';
   area.append(self,hand,tip);
  }
  scene.append(table,area);
  if(mahjongClaimPanel)scene.append(mahjongClaimPanel);
  if(g.status==='playing')scene.append(controls);
 }else{
  scene.append(table);
  if(g.gameType==='cards'){
   const observer=mk('div','wcg-observer-bottom');
   const seat=tableSeat(g,anchor,anchor,renderPlayer);
   seat.className+=' wcg-self-seat';
   observer.append(seat,mk('p','wcg-observer-caption','旁观对局 · 仅展示公开牌面'));
   scene.append(observer);
  }else{
   table.append(tableSeat(g,anchor,anchor,renderPlayer));
   scene.append(mk('p','wcg-observer-caption','正在旁观角色对局 · 仅展示公开的牌面'));
  }
 }
 return scene;
}
function render(g,{canPlay=false,onMove=()=>{},renderPlayer=null}={}){
 if(!g||!TYPES[g.gameType])return mk('p','','游戏记录无效');
 const root=mk('div','wcg-wrap wcg-theme-'+g.gameType+(g.gameType==='gomoku'?'':' wcg-wrap-table'));
 const heading=mk('div','wcg-heading');
 if(g.gameType==='gomoku'){
  heading.className+=' wcg-gomoku-turn';
  heading.append(
   mk('span','wcg-gomoku-turn-label',g.status==='finished'?(g.result||'对局结束'):'轮到 '+g.players[g.turn].name+' · '+(g.turn===0?'黑棋':'白棋')),
   mk('small','', '已落 '+String(g.moves.length).padStart(2,'0')+' 手')
  );
 }else{
  heading.append(mk('strong','',TYPES[g.gameType].name),
   mk('small','',g.status==='finished'?(g.result||'已结束'):'轮到 '+g.players[g.turn].name));
  root.append(heading);
 }
 if(g.gameType==='gomoku'){
  const versus=typeof renderPlayer==='function',seats=mk('div',versus?'wcg-versus':'wcg-seats');
  g.players.forEach((p,i)=>{
   if(versus){if(i)seats.append(mk('span','wcg-vs','VS'));seats.append(renderPlayer(p,i,g.turn===i&&g.status==='playing'));return;}
   const node=mk('div','wcg-seat'+(g.turn===i&&g.status==='playing'?' active':''));
   node.append(mk('b','',p.name),mk('small','', '第 '+(i+1)+' 席'));seats.append(node);
  });
  const matchMeta=mk('div','wcg-gomoku-match-meta');
  const matchTitle=mk('div','wcg-gomoku-match-title');
  matchTitle.append(mk('strong','','好友对弈'),mk('small','wcg-gomoku-match-label','GOMOKU · FRIENDLY MATCH'));
  matchMeta.append(
   matchTitle,
   mk('span','wcg-gomoku-round-pill','第 '+String(Math.floor(g.moves.length/2)+1).padStart(2,'0')+' 回合')
  );
  root.append(matchMeta,seats,heading);
  const grid=mk('div','wcg-gomoku');grid.setAttribute('role','grid');
  const me=g.players.findIndex(p=>p.id==='user');
  g.board.forEach((id,i)=>{
   const black=Boolean(id)&&id===g.players[0].id;
   const cell=btn('','wcg-cell'+(id?' filled':'')+(black?' black':id?' white':'')+([48,56,112,168,176].includes(i)?' star':'')+(g.lastIndex===i?' latest':''),()=>onMove({at:i}),
    !canPlay||me!==g.turn||Boolean(id));
   if(id){const stone=mk('span','wcg-stone');stone.setAttribute('aria-hidden','true');cell.append(stone);}
   cell.setAttribute('aria-label',(Math.floor(i/15)+1)+'行'+(i%15+1)+'列'+(id?(black?'，黑子':'，白子'):'，空位')+(g.lastIndex===i?'，上一手':''));
   grid.append(cell);
  });
  const stage=mk('div','wcg-gomoku-board-stage');
  const barrage=mk('div','wcg-gomoku-barrage');barrage.setAttribute('aria-hidden','true');
  stage.append(grid);
  const frame=mk('section','wcg-gomoku-board-frame');
  const caption=mk('div','wcg-gomoku-board-caption');
  caption.append(mk('b','','棋 · 局'),mk('span','','15 × 15 · STANDARD'));
  const footer=mk('div','wcg-gomoku-board-foot');
  const spectators=mk('span','wcg-gomoku-spectator-count','围观聊天');
  const eye=mk('span','wcg-gomoku-eye');
  // Tabler Icons Filled (MIT): this embedded mark also renders offline.
  eye.innerHTML='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" width="13" height="13" aria-hidden="true"><path d="M12 4c4.29 0 7.863 2.429 10.665 7.154l.22 .379l.045 .1l.03 .083l.014 .055l.014 .082l.011 .1v.11l-.014 .111a.992 .992 0 0 1 -.026 .11l-.039 .108l-.036 .075l-.016 .03c-2.764 4.836 -6.3 7.38 -10.555 7.499l-.313 .004c-4.396 0 -8.037 -2.549 -10.868 -7.504a1 1 0 0 1 0 -.992c2.831 -4.955 6.472 -7.504 10.868 -7.504zm0 5a3 3 0 1 0 0 6a3 3 0 0 0 0 -6"/></svg>';
  const watch=mk('span','wcg-gomoku-viewers');
  watch.append(eye,spectators);
  footer.append(watch,mk('span','wcg-gomoku-board-rule','黑棋先行 · 连五获胜'));
  frame.append(caption,stage,footer);
  root.append(frame,barrage);
 }else root.append(renderTable(g,{canPlay,onMove,renderPlayer}));
 root.append(mk('small','wcg-recent','已经进行 '+g.moves.length+' 手 · 游戏没有真实货币或奖惩'));
 return root;
}

